import { chromium } from 'playwright'

const browser = await chromium.launch()
const page = await browser.newPage()

const apiCalls = []
page.on('request', (req) => {
  const url = req.url()
  if (url.includes('/api/catalog')) apiCalls.push(url)
})

// 1) Visit home, check prefetch fires for both categories without any click.
await page.goto('http://localhost:3100/')
await page.waitForTimeout(1200) // longer than the artificial 800ms server delay
console.log('API calls after visiting / (no click yet):', apiCalls)

// 2) Click the "Products on sale" link and check content appears instantly.
apiCalls.length = 0
const clickStart = Date.now()
await page.click('text=Products on sale')
// Poll immediately for content, and check "Loading category..." never appears.
let sawLoading = false
let sawHeading = false
for (let i = 0; i < 20; i++) {
  const bodyText = await page.textContent('main')
  if (bodyText.includes('Loading category')) sawLoading = true
  if (bodyText.includes('Products on sale') && bodyText.includes('Canvas Tote')) {
    sawHeading = true
    break
  }
  await page.waitForTimeout(10)
}
const elapsed = Date.now() - clickStart
console.log(`Click -> content visible after ${elapsed}ms. sawLoadingFlash=${sawLoading} sawHeading=${sawHeading}`)
console.log('URL after click:', page.url())
console.log('New API calls triggered by click (should be none if cache already warm):', apiCalls)

// 3) Cold direct navigation to /catalog?category=sale in a fresh context (no prefetch).
const page2 = await browser.newPage()
await page2.goto('http://localhost:3100/catalog?category=sale')
const immediateText = await page2.textContent('main')
console.log('Immediately after cold nav, main text includes "Loading category":', immediateText.includes('Loading category'))
await page2.waitForTimeout(1200)
const finalText = await page2.textContent('main')
console.log('After waiting, main text:', finalText.replace(/\s+/g, ' ').trim())

await browser.close()

